"""Test harness: run candidate driver through launch.py like the real verifier."""
import importlib.util, json, os, subprocess, sys, selectors, signal, time
from pathlib import Path
BASE = Path('/workspace')
spec = importlib.util.spec_from_file_location('g', BASE/'child_guard.py')
guard = importlib.util.module_from_spec(spec); spec.loader.exec_module(guard)

def run(data, candidate=BASE/'project', timeout=180):
    env = dict(PATH='/usr/local/bin:/usr/bin:/bin', HOME='/workspace', LANG='C',
               LC_ALL='C', TMPDIR='/workspace/tmp', PYTHONHASHSEED='0',
               PYTHONDONTWRITEBYTECODE='1', PYTHONUNBUFFERED='1')
    p = subprocess.Popen([sys.executable,'-I','-B',str(BASE/'launch.py'),str(candidate)],
                         stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE,
                         env=env,cwd='/workspace',preexec_fn=guard.restrict,close_fds=True)
    pidfd = guard.pidfd_open(p.pid)
    deadline = time.monotonic()+timeout
    sel = selectors.DefaultSelector(); out=[bytearray(),bytearray()]; off=0
    try:
        for s in (p.stdin,p.stdout,p.stderr): os.set_blocking(s.fileno(),False)
        if data: sel.register(p.stdin,selectors.EVENT_WRITE,-1)
        else: p.stdin.close()
        sel.register(p.stdout,selectors.EVENT_READ,0); sel.register(p.stderr,selectors.EVENT_READ,1)
        while sel.get_map():
            rem = deadline-time.monotonic()
            if rem <= 0: raise ValueError('timeout')
            for k,_ in sel.select(min(.2,rem)):
                st,i = k.fileobj,k.data
                if i == -1:
                    try: off += os.write(st.fileno(), data[off:off+65536])
                    except BlockingIOError: continue
                    except BrokenPipeError: off = len(data)
                    if off == len(data): sel.unregister(st); st.close()
                else:
                    cap = (256*1024**2, 1024**2)[i]
                    try: b = os.read(st.fileno(), min(65536, cap-len(out[i])+1))
                    except BlockingIOError: continue
                    if not b: sel.unregister(st); st.close()
                    else:
                        out[i].extend(b)
                        if len(out[i]) > cap: raise ValueError('output cap')
        status = p.wait(timeout=max(.001,deadline-time.monotonic()))
        if status != 0: raise ValueError('exit %s stderr=%s' % (status, bytes(out[1])[:2000]))
        return bytes(out[0]), bytes(out[1])
    finally:
        if p.poll() is None: guard.pidfd_kill(pidfd)
        p.wait(); os.close(pidfd); sel.close()
        for s in (p.stdin,p.stdout,p.stderr): s.close()

def jrun(request):
    """Run one request, return parsed stdout."""
    if not isinstance(request,(bytes,bytearray)):
        request = json.dumps(request).encode()
    out, err = run(request)
    return json.loads(out.decode('utf-8')), err

FAILS = []
def check(name, got, want):
    if got != want:
        FAILS.append(name)
        print('FAIL %s\n  got  %s\n  want %s' % (name, json.dumps(got)[:600], json.dumps(want)[:600]))
    else:
        print('ok   %s' % name)

def summary():
    print('\n%d failures' % len(FAILS))
    return 1 if FAILS else 0

LIM = {'images':16,'cells':262144,'units':1024,'contexts':32768,'connections':4096,'packets':32768,'files':8192}
def job(services, events, limits=None):
    return {'services':services,'limits':limits or dict(LIM),'events':events}
